// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { DeltaPill } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Display/DeltaPill)

figma.connect(DeltaPill, FIGMA_NODE_URL, {
  props: {
    context: figma.string('context'),
    label: figma.string('label'),
    arrow: figma.enum('arrow', { 'none': 'none', 'up': 'up', 'down': 'down' }),
  },
  example: ({ label, context, arrow }) => (
    <DeltaPill context={context} arrow={arrow}>{label}</DeltaPill>
  ),
});
